"""
16 Divisional Charts (Shodasha Vargas) — configurable rule engine
------------------------------------------------------------------
Every Varga is computed from a *named convention*. Nothing is assumed
silently: the active convention for each Varga is part of the chart
configuration and is printed alongside the results.

Conventions available for most Vargas:
  * parashari   — classical BPHS rule (sign-category / parity based)
  * parivritti  — cyclic (parivritti-traya) counting from Mesha

Reference: Brihat Parashara Hora Shastra (BPHS), Vargas Adhyaya
"""

# Generated by GitHub Copilot - Sep-27-2026

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Callable, Iterable

from .planets import RASHI_NAMES, RASHI_LORDS


@dataclass
class VargaPosition:
    rashi_index: int
    rashi: str
    rashi_lord: str
    varga: str = ""          # e.g. "D9"
    divisions: int = 1
    convention: str = ""     # convention actually used


def _rashi(idx: int) -> VargaPosition:
    idx = idx % 12
    r = RASHI_NAMES[idx]
    return VargaPosition(rashi_index=idx, rashi=r, rashi_lord=RASHI_LORDS[r])


# ── Sign helpers ──────────────────────────────────────────────────────────────

def _parts(lon: float, divisions: int) -> tuple[int, float, int]:
    """Return (rashi_index, degree_in_rashi, part_index 0..divisions-1)."""
    rashi = int(lon // 30) % 12
    deg = lon % 30.0
    part = int(deg / (30.0 / divisions))
    return rashi, deg, min(part, divisions - 1)


def is_odd_sign(rashi_index: int) -> bool:
    """Mesha, Mithuna, Simha ... are the odd (vishama) signs."""
    return rashi_index % 2 == 0


def movability(rashi_index: int) -> int:
    """0 = chara (movable), 1 = sthira (fixed), 2 = dwiswabhava (dual)."""
    return rashi_index % 3


def element(rashi_index: int) -> int:
    """0 = fire, 1 = earth, 2 = air, 3 = water."""
    return rashi_index % 4


# ── Generic convention builders ───────────────────────────────────────────────

RuleFn = Callable[[float], int]


def _parivritti(divisions: int) -> RuleFn:
    """Cyclic counting: the 12*n divisions run continuously from Mesha."""
    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        return (rashi * divisions + part) % 12
    return rule


def _from_own(divisions: int) -> RuleFn:
    """Count the parts forward starting from the occupied sign."""
    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        return (rashi + part) % 12
    return rule


def _own_with_offsets(divisions: int, offsets: Iterable[int]) -> RuleFn:
    """Each part maps to a fixed offset from the occupied sign (D3, D4)."""
    offs = list(offsets)

    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        return (rashi + offs[part]) % 12
    return rule


def _parity_offset(divisions: int, odd_offset: int, even_offset: int) -> RuleFn:
    """Start from the occupied sign shifted by a parity-dependent offset."""
    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        offset = odd_offset if is_odd_sign(rashi) else even_offset
        return (rashi + offset + part) % 12
    return rule


def _parity_start(divisions: int, odd_start: int, even_start: int) -> RuleFn:
    """Start from a fixed sign chosen by the parity of the occupied sign."""
    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        start = odd_start if is_odd_sign(rashi) else even_start
        return (start + part) % 12
    return rule


def _category_start(divisions: int, categorize: Callable[[int], int],
                    starts: Iterable[int]) -> RuleFn:
    """Start from a fixed sign chosen by sign category (movability/element)."""
    st = list(starts)

    def rule(lon: float) -> int:
        rashi, _, part = _parts(lon, divisions)
        return (st[categorize(rashi)] + part) % 12
    return rule


# ── Special-case rules ────────────────────────────────────────────────────────

def _hora_parashari(lon: float) -> int:
    """Odd sign: 1st half Surya's hora (Simha), 2nd half Chandra's (Karka)."""
    rashi, deg, _ = _parts(lon, 2)
    first_half = deg < 15.0
    if is_odd_sign(rashi):
        return 4 if first_half else 3       # Simha / Karka
    return 3 if first_half else 4           # Karka / Simha


# Trimshamsha is the one Varga with *unequal* parts (5/5/8/7/5 degrees).
_TRIMSHAMSHA_ODD_BOUNDS = [5.0, 10.0, 18.0, 25.0, 30.0]
_TRIMSHAMSHA_EVEN_BOUNDS = [5.0, 12.0, 20.0, 25.0, 30.0]
# Parashari: lords Mangal, Shani, Guru, Budha, Shukra — odd signs take the
# odd-footed house of each lord, even signs the even-footed one, in reverse order.
_TRIMSHAMSHA_ODD_SIGNS = [0, 10, 8, 2, 6]     # Mesha, Kumbha, Dhanu, Mithuna, Tula
_TRIMSHAMSHA_EVEN_SIGNS = [1, 5, 11, 9, 7]    # Vrishabha, Kanya, Meena, Makara, Vrishchika


def _trimshamsha_parashari(lon: float) -> int:
    """BPHS Trimshamsha: unequal parts ruled by the five non-luminaries."""
    rashi, deg, _ = _parts(lon, 1)
    if is_odd_sign(rashi):
        bounds, signs = _TRIMSHAMSHA_ODD_BOUNDS, _TRIMSHAMSHA_ODD_SIGNS
    else:
        bounds, signs = _TRIMSHAMSHA_EVEN_BOUNDS, _TRIMSHAMSHA_EVEN_SIGNS
    for bound, sign in zip(bounds, signs):
        if deg < bound:
            return sign
    return signs[-1]


def _trimshamsha_movable_lords(lon: float) -> int:
    """Variant mapping Shani to Makara and Mangal to Mesha for both parities."""
    rashi, deg, _ = _parts(lon, 1)
    if is_odd_sign(rashi):
        bounds, signs = _TRIMSHAMSHA_ODD_BOUNDS, [0, 9, 8, 2, 6]
    else:
        bounds, signs = _TRIMSHAMSHA_EVEN_BOUNDS, [6, 2, 8, 9, 0]
    for bound, sign in zip(bounds, signs):
        if deg < bound:
            return sign
    return signs[-1]


def _shashtiamsha_reverse_even(lon: float) -> int:
    """Shashtiamsha counted in reverse for even signs (some traditions)."""
    rashi, _, part = _parts(lon, 60)
    if is_odd_sign(rashi):
        return (rashi + part) % 12
    return (rashi - part) % 12


# ── Convention registry ───────────────────────────────────────────────────────

@dataclass(frozen=True)
class Convention:
    rule: RuleFn
    description: str


@dataclass(frozen=True)
class VargaSpec:
    key: str
    divisions: int
    name: str
    purpose: str
    conventions: dict[str, Convention]
    default: str


def _spec(key, divisions, name, purpose, conventions, default) -> VargaSpec:
    return VargaSpec(key=key, divisions=divisions, name=name, purpose=purpose,
                     conventions=conventions, default=default)


