VARGA_ORDER = list(VARGA_SPECS.keys())

DEFAULT_CONVENTIONS: dict[str, str] = {k: s.default for k, s in VARGA_SPECS.items()}


# ── Configuration ─────────────────────────────────────────────────────────────

class VargaConfigError(ValueError):
    """Raised when a requested Varga or convention is not registered."""


@dataclass
class VargaConfig:
    """Selected convention per Varga — explicit methodology, never implicit."""

    conventions: dict[str, str] = field(
        default_factory=lambda: dict(DEFAULT_CONVENTIONS))
    source: str = "built-in defaults"

    def __post_init__(self):
        merged = dict(DEFAULT_CONVENTIONS)
        for key, conv in self.conventions.items():
            if key not in VARGA_SPECS:
                raise VargaConfigError(
                    f"Unknown varga '{key}'. Known: {', '.join(VARGA_ORDER)}")
            if conv not in VARGA_SPECS[key].conventions:
                allowed = ", ".join(VARGA_SPECS[key].conventions)
                raise VargaConfigError(
                    f"Unknown convention '{conv}' for {key}. Available: {allowed}")
            merged[key] = conv
        self.conventions = merged

    @classmethod
    def from_file(cls, path: str) -> "VargaConfig":
        """Load conventions from JSON: {"conventions": {"D2": "parivritti"}}."""
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if not isinstance(data, dict):
            raise VargaConfigError(f"{path}: expected a JSON object")
        conventions = data.get("conventions", data)
        if not isinstance(conventions, dict):
            raise VargaConfigError(f"{path}: 'conventions' must be an object")
        return cls(conventions={str(k): str(v) for k, v in conventions.items()},
                   source=path)

    def convention_for(self, key: str) -> str:
        if key not in VARGA_SPECS:
            raise VargaConfigError(f"Unknown varga '{key}'")
        return self.conventions[key]

    def compute(self, key: str, sidereal_lon: float) -> VargaPosition:
        """Compute one Varga position using the configured convention."""
        spec = VARGA_SPECS.get(key)
        if spec is None:
            raise VargaConfigError(f"Unknown varga '{key}'")
        conv_name = self.conventions[key]
        pos = _rashi(spec.conventions[conv_name].rule(sidereal_lon % 360.0))
        pos.varga = key
        pos.divisions = spec.divisions
        pos.convention = conv_name
        return pos

    def compute_all(self, sidereal_lon: float) -> dict[str, VargaPosition]:
        """Compute all 16 Varga positions for one sidereal longitude."""
        return {key: self.compute(key, sidereal_lon) for key in VARGA_ORDER}

    def describe(self) -> str:
        """Human-readable summary of the methodology in force."""
        lines = [f"  Varga methodology (source: {self.source})",
                 f"  {'Chart':<5} {'Name':<18} {'Convention':<15} Rule",
                 "  " + "─" * 88]
        for key in VARGA_ORDER:
            spec = VARGA_SPECS[key]
            conv = self.conventions[key]
            lines.append(f"  {key:<5} {spec.name:<18} {conv:<15} "
                         f"{spec.conventions[conv].description}")
        return "\n".join(lines)


DEFAULT_CONFIG = VargaConfig()


# ── Public API ────────────────────────────────────────────────────────────────

def compute_all_vargas(sidereal_lon: float,
                       config: VargaConfig | None = None) -> dict[str, VargaPosition]:
    """
    Given a body's sidereal longitude, compute its sign in all 16 Vargas
    using the supplied configuration (built-in defaults when omitted).
    """
    return (config or DEFAULT_CONFIG).compute_all(sidereal_lon)


def available_conventions() -> dict[str, list[str]]:
    """Map each Varga key to the convention names it supports."""
    return {key: list(spec.conventions) for key, spec in VARGA_SPECS.items()}


# Backwards-compatible view used by older callers: key -> (fn, name, purpose)
VARGA_FUNCTIONS: dict[str, tuple[Callable[[float], VargaPosition], str, str]] = {
    key: ((lambda k: (lambda lon: DEFAULT_CONFIG.compute(k, lon)))(key),
          spec.name, spec.purpose)
    for key, spec in VARGA_SPECS.items()
}


def print_varga_table(body_name: str, sidereal_lon: float,
                      config: VargaConfig | None = None):
    """Print all Varga positions for one body, including the convention used."""
    cfg = config or DEFAULT_CONFIG
    vargas = cfg.compute_all(sidereal_lon)
    print(f"\n  Varga positions for {body_name} (sidereal {sidereal_lon:.4f}°):")
    print(f"  {'Div':<6} {'Name':<18} {'Rashi':<12} {'Lord':<9} "
          f"{'Convention':<14} {'Purpose'}")
    print(f"  {'─' * 96}")
    for key in VARGA_ORDER:
        v = vargas[key]
        spec = VARGA_SPECS[key]
        print(f"  {key:<6} {spec.name:<18} {v.rashi:<12} {v.rashi_lord:<9} "
              f"{v.convention:<14} {spec.purpose}")
